+    const hint = document.querySelector('#hint');
+    const empty = document.querySelector('#empty');
+    const bookmarks = document.querySelector('#bookmarks');
+    const count = document.querySelector('#count');
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+      button.disabled = true;
+      button.textContent = 'Gathering details…';
+      status.textContent = 'Reading the page…';
+
+      window.setTimeout(() => {
+        empty.hidden = true;
+        hint.hidden = true;
+        bookmarks.innerHTML = `
+          <a class="bookmark" href="https://www.seriouseats.com/roman-pasta-recipes-5117829" target="_blank" rel="noreferrer">
+            <svg class="preview" viewBox="0 0 232 184" role="img" aria-label="Bowl of pasta illustration" xmlns="http://www.w3.org/2000/svg">
+              <rect width="232" height="184" fill="#e7d6b8"/>
+              <circle cx="116" cy="92" r="67" fill="#f7f0dd"/>
+              <circle cx="116" cy="92" r="48" fill="#d99442"/>
+              <path d="M77 73c23 35 63 5 79 34M71 91c28-31 61 23 91-7M84 115c20-26 45 15 70-12" fill="none" stroke="#f4cf71" stroke-width="9" stroke-linecap="round"/>
+              <g fill="#47744b"><circle cx="93" cy="73" r="5"/><circle cx="135" cy="111" r="5"/><circle cx="145" cy="77" r="4"/></g>
+            </svg>
+            <div>
+              <div class="source"><span class="favicon">S</span> seriouseats.com</div>
+              <h3>Essential Roman Pasta Recipes</h3>
+              <p>Master the four classic pasta dishes of Rome, from silky cacio e pepe to deeply savory amatriciana.</p>
+            </div>
+          </a>`;
+        count.textContent = '1 saved';
+        status.textContent = 'Saved with title, description, site icon, and preview.';
+        button.disabled = false;
+        button.textContent = 'Save link';
+        input.value = '';
+      }, 700);
+    });
+  </script>
+</body>
+</html>
