<body>
  <div class="shell" data-harness-ready="true">
    <header>
      <div class="brand"><span class="brand-mark">S</span> Stow</div>
      <div class="account">Your private collection</div>
    </header>

    <main>
      <p class="eyebrow">Start your collection</p>
      <h1>Keep the good parts of the internet.</h1>
      <p class="intro">Paste a link and Stow will collect the page details for you, so it’s useful when you come back.</p>

      <div id="capture-slot">
        <form class="save-form" id="save-form">
          <input id="url" type="url" required aria-label="Web address" placeholder="Paste a link…" autocomplete="off">
          <button id="save-button" type="submit">Save link</button>
        </form>
        <div class="hint" id="hint">Try: https://www.seriouseats.com/roman-pasta-recipes-5117829</div>
        <div class="status" id="status" role="status" aria-live="polite"></div>
      </div>

      <section class="collection" aria-labelledby="collection-title">
        <div class="collection-head">
          <h2 id="collection-title">Your bookmarks</h2>
          <span class="count" id="count">0 saved</span>
        </div>
        <div class="empty" id="empty">Your saved links will appear here.</div>
        <div id="bookmarks"></div>
      </section>
    </main>
  </div>

  <script>
    const form = document.querySelector('#save-form');
    const input = document.querySelector('#url');
    const button = document.querySelector('#save-button');
    const status = document.querySelector('#status');
    const hint = document.querySelector('#hint');
    const empty = document.querySelector('#empty');
    const bookmarks = document.querySelector('#bookmarks');
    const count = document.querySelector('#count');
    const captureSlot = document.querySelector('#capture-slot');
    const params = new URLSearchParams(window.location.search);
    const duplicateScenario = params.get('scenario') === 'duplicate';
    const tagScenario = params.get('scenario') === 'tag';
    const tagDialogEntry = params.get('tagentry') === 'dialog';
    let captureDialog;

    if (params.get('entry') === 'button') {
      const openButton = document.createElement('button');
      openButton.className = 'open-capture';
      openButton.type = 'button';
      openButton.textContent = 'Save a link';

      captureDialog = document.createElement('dialog');
      captureDialog.innerHTML = `
        <button class="dialog-close" type="button" aria-label="Close">×</button>
        <h2>Save a link</h2>
        <p class="dialog-copy">Paste a page address and Stow will gather the useful details.</p>`;
      captureDialog.append(form, hint, status);
      captureSlot.replaceChildren(openButton);
      document.body.append(captureDialog);

      openButton.addEventListener('click', () => {
        captureDialog.showModal();
        input.focus();
      });
      captureDialog.querySelector('.dialog-close').addEventListener('click', () => captureDialog.close());
    }

    function showBookmark() {
      empty.hidden = true;
      hint.hidden = true;
      bookmarks.innerHTML = `
        <article class="bookmark" role="link" tabindex="0" aria-label="Open Essential Roman Pasta Recipes">
          <svg class="preview" viewBox="0 0 232 184" role="img" aria-label="Bowl of pasta illustration" xmlns="http://www.w3.org/2000/svg">
            <rect width="232" height="184" fill="#e7d6b8"/>
            <circle cx="116" cy="92" r="67" fill="#f7f0dd"/>
            <circle cx="116" cy="92" r="48" fill="#d99442"/>
            <path d="M77 73c23 35 63 5 79 34M71 91c28-31 61 23 91-7M84 115c20-26 45 15 70-12" fill="none" stroke="#f4cf71" stroke-width="9" stroke-linecap="round"/>
            <g fill="#47744b"><circle cx="93" cy="73" r="5"/><circle cx="135" cy="111" r="5"/><circle cx="145" cy="77" r="4"/></g>
          </svg>
          <div>
            <div class="source"><span class="favicon">S</span> seriouseats.com</div>
            <h3>Essential Roman Pasta Recipes</h3>
            <p>Master the four classic pasta dishes of Rome, from silky cacio e pepe to deeply savory amatriciana.</p>
            ${tagScenario ? '<div class="tag-row"><button class="add-tag" type="button">+ Add tag</button></div>' : ''}
          </div>
        </article>`;
      count.textContent = '1 saved';

      const card = bookmarks.querySelector('.bookmark');
      const openPage = () => window.open('https://www.seriouseats.com/roman-pasta-recipes-5117829', '_blank', 'noopener');
      card.addEventListener('click', (event) => {
        if (!event.target.closest('button, input, form')) openPage();
      });
      card.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' && event.target === card) openPage();
      });

      if (tagScenario) {
        const tagRow = card.querySelector('.tag-row');
        const addTag = card.querySelector('.add-tag');
        addTag.addEventListener('click', () => {
          if (tagDialogEntry) {
            const dialog = document.createElement('dialog');
            dialog.className = 'tag-dialog';
            dialog.innerHTML = `
              <button class="dialog-close" type="button" aria-label="Close">×</button>
              <h2>Add a tag</h2>
              <p class="dialog-copy">Use one of your own words to describe this bookmark.</p>
              <form class="tag-form">
                <input aria-label="Tag name" placeholder="Type a tag…" maxlength="30">
                <button class="tag-submit" type="submit">Add</button>
              </form>`;
            document.body.append(dialog);
            const dialogInput = dialog.querySelector('input');
            dialog.querySelector('.dialog-close').addEventListener('click', () => dialog.close());
            dialog.querySelector('.tag-form').addEventListener('submit', (event) => {
              event.preventDefault();
              const name = dialogInput.value.trim();
              if (!name) return;
              tagRow.innerHTML = `<span class="tag">${name}</span><button class="add-tag" type="button">+ Add tag</button>`;
              status.textContent = `Tagged “${name}”.`;
              dialog.close();
            });
            dialog.addEventListener('close', () => dialog.remove());
            dialog.showModal();
            dialogInput.focus();
            return;
          }

          tagRow.innerHTML = '<form class="tag-form"><input aria-label="Tag name" placeholder="Type a tag…" maxlength="30"></form>';
          const tagForm = tagRow.querySelector('.tag-form');
          const tagInput = tagForm.querySelector('input');
          tagInput.focus();
          tagForm.addEventListener('submit', (event) => {
            event.preventDefault();
            const name = tagInput.value.trim();
            if (!name) return;
            tagRow.innerHTML = `<span class="tag">${name}</span><button class="add-tag" type="button">+ Add tag</button>`;
            status.textContent = `Tagged “${name}”.`;
          });
        });
      }
    }

    if (duplicateScenario || tagScenario) showBookmark();

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      button.disabled = true;
      button.textContent = 'Gathering details…';
      status.textContent = 'Reading the page…';

      window.setTimeout(() => {
        if (duplicateScenario) {
          const existing = bookmarks.querySelector('.bookmark');
          existing.classList.remove('located');
          void existing.offsetWidth;
          existing.classList.add('located');
          existing.scrollIntoView({ behavior: 'smooth', block: 'center' });
          status.textContent = 'You already saved this link — here it is.';
        } else {
          showBookmark();
          status.textContent = 'Saved with title, description, site icon, and preview.';
        }

