    }

    .tag-form { display: flex; gap: 7px; }

    .tag-form input {
      width: 150px;
      min-height: 30px;
      border: 1px solid #9eb2a8;
      border-radius: 8px;
      outline: none;
      padding: 5px 9px;
      background: white;
      font-size: 13px;
    }

    .tag-form input:focus { box-shadow: 0 0 0 3px rgba(35, 107, 82, .12); }

    .tag-entry { position: relative; }

    .tag-suggestions {
      position: absolute;
      z-index: 3;
      top: calc(100% + 5px);
      left: 0;
      width: 190px;
      padding: 5px;
      border: 1px solid var(--line);
      border-radius: 10px;
      background: white;
      box-shadow: 0 12px 28px rgba(38, 55, 48, .14);
    }

    .tag-suggestion {
      width: 100%;
      border: 0;
      border-radius: 7px;
      padding: 8px 9px;
      color: var(--ink);
      background: var(--soft);
      cursor: pointer;
      text-align: left;
      font-weight: 700;
    }

    @keyframes rise {
      from { opacity: 0; transform: translateY(7px); }
      to { opacity: 1; transform: translateY(0); }
    }

    @keyframes locate {
      0%, 100% { box-shadow: 0 12px 30px rgba(38, 55, 48, .07); }
      35% { border-color: var(--accent); box-shadow: 0 0 0 5px rgba(35, 107, 82, .15); }
    }

    @media (max-width: 620px) {
      .shell { width: min(100% - 24px, 960px); padding-top: 20px; }
      header { margin-bottom: 42px; }
      .account { display: none; }
      .save-form { display: grid; }
      .save-form button { width: 100%; }
      .bookmark { grid-template-columns: 1fr; }
      .preview { width: 100%; height: 150px; }
    }
