+    .replace(/<\/?[^>]+>|[^<]+/g, (token) => {
+      if (!token.startsWith('<')) {
+        return token
+          .replaceAll('&', '&amp;')
+          .replaceAll('<', '&lt;')
+          .replaceAll('>', '&gt;');
+      }
+      const match = token.match(/^<\s*(\/?)\s*([a-z0-9]+)[^>]*>$/i);
+      if (!match) return '';
+      const closing = Boolean(match[1]);
+      const tag = match[2].toLowerCase();
+      if (!ALLOWED_TAGS.has(tag)) return '';
+      if (tag === 'br') return '<br>';
+      return `<${closing ? '/' : ''}${tag}>`;
+    });
