  if (!last) return url.hostname.replace(/^www\./, '');
  try {
    return decodeURIComponent(last)
      .replace(/[-_]+/g, ' ')
      .replace(/\.[a-z0-9]{1,6}$/i, '')
      .trim() || url.hostname.replace(/^www\./, '');
  } catch {
    return last;
  }
}
