  const resolve = (candidate, fallback = '') => {
    if (!candidate) return fallback;
    try {
      const resolved = new URL(candidate, page).toString();
      return ['http:', 'https:'].includes(new URL(resolved).protocol) ? resolved : fallback;
    } catch {
      return fallback;
    }
  };

