const ENTITY_MAP = {
  amp: '&',
  apos: "'",
  gt: '>',
  lt: '<',
  nbsp: ' ',
  quot: '"'
};

export function decodeEntities(value = '') {
  return String(value).replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (entity, code) => {
    if (code[0] === '#') {
      const radix = code[1]?.toLowerCase() === 'x' ? 16 : 10;
      const raw = radix === 16 ? code.slice(2) : code.slice(1);
      const point = Number.parseInt(raw, radix);
      return Number.isFinite(point) ? String.fromCodePoint(point) : entity;
    }
    return ENTITY_MAP[code.toLowerCase()] ?? entity;
  });
}

export function stripTags(value = '') {
  return decodeEntities(
    String(value)
      .replace(/<(br|\/p|\/div|\/li)>/gi, '\n')
      .replace(/<[^>]*>/g, '')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const ALLOWED_TAGS = new Set(['b', 'strong', 'em', 'ul', 'ol', 'li', 'p', 'div', 'br']);

export function sanitizeRichText(value = '') {
  return String(value)
    .replace(/<!--([\s\S]*?)-->/g, '')
    .replace(/<\/?[^>]+>|[^<]+/g, (token) => {
      if (!token.startsWith('<')) {
        return token
          .replaceAll('&', '&amp;')
          .replaceAll('<', '&lt;')
          .replaceAll('>', '&gt;');
      }
      const match = token.match(/^<\s*(\/?)\s*([a-z0-9]+)[^>]*>$/i);
      if (!match) return '';
      const closing = Boolean(match[1]);
      const tag = match[2].toLowerCase();
      if (!ALLOWED_TAGS.has(tag)) return '';
      if (tag === 'br') return '<br>';
      return `<${closing ? '/' : ''}${tag}>`;
    });
}
import dns from 'node:dns/promises';
import net from 'node:net';

const TRACKING_KEYS = new Set([
  'fbclid',
  'gclid',
  'dclid',
  'msclkid',
  'mc_cid',
  'mc_eid',
  'igshid',
  'ref_src'
]);

export function parseWebUrl(value) {
  let url;
  try {
    url = new URL(String(value).trim());
  } catch {
    const error = new Error('Enter a full web address, like https://example.com/page.');
    error.code = 'INVALID_URL';
    throw error;
  }
  if (!['http:', 'https:'].includes(url.protocol)) {
    const error = new Error('Enter a full web address beginning with http:// or https://.');
    error.code = 'INVALID_URL';
    throw error;
  }
  url.username = '';
  url.password = '';
  return url;
}

export function canonicalizeUrl(value) {
  const url = parseWebUrl(value);
  url.hash = '';
  for (const key of [...url.searchParams.keys()]) {
    const lower = key.toLowerCase();
    if (lower.startsWith('utm_') || TRACKING_KEYS.has(lower)) url.searchParams.delete(key);
  }
  if ((url.protocol === 'https:' && url.port === '443') || (url.protocol === 'http:' && url.port === '80')) {
    url.port = '';
  }
  if (url.pathname === '') url.pathname = '/';
  return url.toString();
}

export function sameUnderlyingPage(left, right) {
  return canonicalizeUrl(left) === canonicalizeUrl(right);
}

function isPrivateIPv4(ip) {
  const parts = ip.split('.').map(Number);
  if (parts.length !== 4 || parts.some((part) => !Number.isInteger(part))) return true;
  const [a, b] = parts;
  return a === 0
    || a === 10
    || a === 127
    || (a === 169 && b === 254)
    || (a === 172 && b >= 16 && b <= 31)
    || (a === 192 && b === 168)
    || a >= 224;
}

function isPrivateIPv6(ip) {
  const normalized = ip.toLowerCase();
  return normalized === '::1'
    || normalized === '::'
    || normalized.startsWith('fc')
    || normalized.startsWith('fd')
    || normalized.startsWith('fe8')
    || normalized.startsWith('fe9')
    || normalized.startsWith('fea')
    || normalized.startsWith('feb');
}

export async function assertPublicAddress(url) {
  const hostname = url.hostname.toLowerCase();
  if (hostname === 'localhost' || hostname.endsWith('.localhost')) {
    const error = new Error('That address cannot be fetched.');
    error.code = 'UNSAFE_ADDRESS';
    throw error;
  }
  const literalFamily = net.isIP(hostname);
  if (literalFamily === 4 && isPrivateIPv4(hostname)) throwUnsafe();
  if (literalFamily === 6 && isPrivateIPv6(hostname)) throwUnsafe();
  if (!literalFamily) {
    const addresses = await dns.lookup(hostname, { all: true, verbatim: true });
    if (!addresses.length) throw new Error('The site could not be found.');
    for (const address of addresses) {
      if ((address.family === 4 && isPrivateIPv4(address.address))
        || (address.family === 6 && isPrivateIPv6(address.address))) throwUnsafe();
    }
  }
}

function throwUnsafe() {
  const error = new Error('That address cannot be fetched.');
  error.code = 'UNSAFE_ADDRESS';
  throw error;
}

